//! Combat events: procs and event-driven aura interrupts.
//!
//! Emitters push `AuraEvent`s into `PendingAuraEvents`; `process_aura_events`
//! drains them in FixedUpdate. Each event has an actor side and a target side,
//! each with `ProcTypeMask_0/_1` bits (TrinityCore `ProcFlags`/`ProcFlags2`).
//!
//! A unit's aura procs when (TrinityCore `CanSpellTriggerProcOnEvent`, with
//! autogenerated proc entries):
//! - `ProcTypeMask` intersects the event side's mask;
//! - one of its effects is a trigger type (`handlers::can_proc`);
//! - for spell events, the event spell matches the aura's `SpellClassSet` and
//!   the union of the trigger effects' `SpellClassMask` (when non-zero);
//! - the event does not come from a triggered spell (`can_proc`), unless the aura
//!   has `SPELL_ATTR3_CAN_PROC_FROM_PROCS` or the triggered spell
//!   `SPELL_ATTR3_NOT_A_PROC`, and it is not the aura's own trigger spell;
//! - `ProcCategoryRecovery` has elapsed;
//! - the roll passes: RPPM (`SpellProcsPerMinute.BaseProcRate`, TrinityCore
//!   `CalcPPMProcChance`) when present, else `ProcChance` (ProcChance mods
//!   applied).
//!
//! A breakable crowd-control effect (`handlers::breaks_on_damage`) takes part
//! only in events that dealt damage, except its own spell's
//! (`AuraEffect::CheckEffectProc`).
//!
//! A proc casts each PROC_TRIGGER_SPELL(_WITH_VALUE) `EffectTriggerSpell`
//! from the aura's unit at the other party (or itself), takes the event's damage
//! off each breakable crowd-control effect and removes the aura when one reaches 0
//! (`HandleBreakableCCAuraProc`), runs the aura's script `on_proc`, then spends
//! one charge.

use crate::random as rand;
use bevy::prelude::*;

use super::handlers::{self, PROC_TRIGGER_SPELL, PROC_TRIGGER_SPELL_WITH_VALUE};
use super::{
    ActiveAuras, AuraEffectState, AuraInstance, SpellModOp, aura_now, scripts, spell_mods,
};
use crate::spell_info::{SpellInfo, SpellStore};

pub const PROC_KILL: u32 = 0x2;
pub const PROC_DEAL_MELEE_SWING: u32 = 0x4;
pub const PROC_TAKE_MELEE_SWING: u32 = 0x8;
pub const PROC_DEAL_MELEE_ABILITY: u32 = 0x10;
pub const PROC_TAKE_MELEE_ABILITY: u32 = 0x20;
pub const PROC_DEAL_RANGED_ABILITY: u32 = 0x100;
pub const PROC_TAKE_RANGED_ABILITY: u32 = 0x200;
pub const PROC_DEAL_HELPFUL_ABILITY: u32 = 0x400;
pub const PROC_TAKE_HELPFUL_ABILITY: u32 = 0x800;
pub const PROC_DEAL_HARMFUL_ABILITY: u32 = 0x1000;
pub const PROC_TAKE_HARMFUL_ABILITY: u32 = 0x2000;
pub const PROC_DEAL_HELPFUL_SPELL: u32 = 0x4000;
pub const PROC_TAKE_HELPFUL_SPELL: u32 = 0x8000;
pub const PROC_DEAL_HARMFUL_SPELL: u32 = 0x10000;
pub const PROC_TAKE_HARMFUL_SPELL: u32 = 0x20000;
pub const PROC_DEAL_HARMFUL_PERIODIC: u32 = 0x40000;
pub const PROC_TAKE_HARMFUL_PERIODIC: u32 = 0x80000;
pub const PROC_TAKE_ANY_DAMAGE: u32 = 0x100000;
pub const PROC_DEAL_HELPFUL_PERIODIC: u32 = 0x200000;
pub const PROC_MAIN_HAND_WEAPON_SWING: u32 = 0x400000;
pub const PROC_OFF_HAND_WEAPON_SWING: u32 = 0x800000;
pub const PROC_DEATH: u32 = 0x0100_0000;
pub const PROC_TAKE_HELPFUL_PERIODIC: u32 = 0x8000_0000;
/// `ProcTypeMask_1` (TrinityCore `ProcFlags2`).
pub const PROC2_CAST_SUCCESSFUL: u32 = 0x4;
/// TC a352b1fa SpellMgr.h:191, recipient-side knockback event.
pub const PROC2_KNOCKBACK: u32 = 0x2;

/// Event bits carried by a spell (not melee swing, kill or death).
const SPELL_PROC_MASK: u32 = PROC_DEAL_MELEE_ABILITY
    | PROC_TAKE_MELEE_ABILITY
    | PROC_DEAL_RANGED_ABILITY
    | PROC_TAKE_RANGED_ABILITY
    | PROC_DEAL_HELPFUL_ABILITY
    | PROC_TAKE_HELPFUL_ABILITY
    | PROC_DEAL_HARMFUL_ABILITY
    | PROC_TAKE_HARMFUL_ABILITY
    | PROC_DEAL_HELPFUL_SPELL
    | PROC_TAKE_HELPFUL_SPELL
    | PROC_DEAL_HARMFUL_SPELL
    | PROC_TAKE_HARMFUL_SPELL
    | PROC_DEAL_HARMFUL_PERIODIC
    | PROC_TAKE_HARMFUL_PERIODIC
    | PROC_DEAL_HELPFUL_PERIODIC
    | PROC_TAKE_HELPFUL_PERIODIC;
const HOSTILE_TAKEN_MASK: u32 = PROC_TAKE_MELEE_SWING
    | PROC_TAKE_MELEE_ABILITY
    | PROC_TAKE_RANGED_ABILITY
    | PROC_TAKE_HARMFUL_ABILITY
    | PROC_TAKE_HARMFUL_SPELL
    | PROC_TAKE_HARMFUL_PERIODIC;

/// `SpellAuraInterruptFlags` raised by events.
const INTERRUPT_HOSTILE_ACTION_RECEIVED: u32 = 0x1;
const INTERRUPT_DAMAGE: u32 = 0x2;
const INTERRUPT_ACTION: u32 = 0x4;
const INTERRUPT_ATTACKING: u32 = 0x1000;
const INTERRUPT_NON_PERIODIC_DAMAGE: u32 = 0x0100_0000;

/// Triggered spells cast by procs resolve at this depth (no proc events).
const PROC_TRIGGER_DEPTH: u8 = 1;
/// RPPM caps the time since the last attempt (TrinityCore: 10 s).
const PPM_MAX_ATTEMPT_GAP: f64 = 10.0;

/// One combat event.
#[derive(Debug, Clone, PartialEq)]
pub struct AuraEvent {
    pub actor: Entity,
    pub target: Option<Entity>,
    pub actor_mask: [u32; 2],
    pub target_mask: [u32; 2],
    pub spell_id: Option<u32>,
    /// False for events of triggered spells (they interrupt but never proc).
    pub can_proc: bool,
    pub periodic: bool,
    /// Damage the event dealt to `target` after absorbs, in its health units (level
    /// scaling); 0 for no damage.
    pub damage: f32,
    /// `PROC_HIT_REFLECT`: `target` reflected the actor's spell (`ProcReflectDelayed`,
    /// Spell.cpp:2412-2436). Only reflect auras proc off it, and only off it.
    pub reflected: bool,
}

#[derive(Resource, Debug, Default)]
pub struct PendingAuraEvents(pub Vec<AuraEvent>);

pub fn push_event(world: &mut World, event: AuraEvent) {
    if let Some(mut pending) = world.get_resource_mut::<PendingAuraEvents>() {
        pending.0.push(event);
    }
}

/// Actor/target masks of a spell landing on a target, by `DefenseType`
/// (TrinityCore DmgClass: 0 none, 1 magic, 2 melee, 3 ranged) and whether
/// the hit is harmful.
pub fn spell_hit_masks(spell: &SpellInfo, harmful: bool) -> (u32, u32) {
    let defense = spell
        .categories
        .as_ref()
        .map_or(0, |categories| categories.defense_type);
    match (defense, harmful) {
        (2, _) => (PROC_DEAL_MELEE_ABILITY, PROC_TAKE_MELEE_ABILITY),
        (3, _) => (PROC_DEAL_RANGED_ABILITY, PROC_TAKE_RANGED_ABILITY),
        (1, true) => (PROC_DEAL_HARMFUL_SPELL, PROC_TAKE_HARMFUL_SPELL),
        (1, false) => (PROC_DEAL_HELPFUL_SPELL, PROC_TAKE_HELPFUL_SPELL),
        (_, true) => (PROC_DEAL_HARMFUL_ABILITY, PROC_TAKE_HARMFUL_ABILITY),
        (_, false) => (PROC_DEAL_HELPFUL_ABILITY, PROC_TAKE_HELPFUL_ABILITY),
    }
}

/// Aura interrupt flags raised on the unit whose side has `mask`.
fn interrupt_flags(mask: [u32; 2], periodic: bool) -> [u32; 2] {
    let mut flags = 0;
    if mask[0] & HOSTILE_TAKEN_MASK != 0 {
        flags |= INTERRUPT_HOSTILE_ACTION_RECEIVED;
    }
    if mask[0] & PROC_TAKE_ANY_DAMAGE != 0 {
        flags |= INTERRUPT_DAMAGE;
        if !periodic {
            flags |= INTERRUPT_NON_PERIODIC_DAMAGE;
        }
    }
    if mask[0] & PROC_DEAL_MELEE_SWING != 0 {
        flags |= INTERRUPT_ATTACKING;
    }
    if mask[1] & PROC2_CAST_SUCCESSFUL != 0 {
        flags |= INTERRUPT_ACTION;
    }
    [flags, 0]
}

pub(super) fn process_aura_events(world: &mut World) {
    let events = std::mem::take(&mut world.resource_mut::<PendingAuraEvents>().0);
    for event in events {
        handle_side(world, event.actor, event.target, event.actor_mask, &event);
        if let Some(target) = event.target {
            if event.damage > 0.0 && !event.periodic {
                super::reduce_cast_pushback(world, target);
            }
            handle_side(world, target, Some(event.actor), event.target_mask, &event);
        }
    }
}

fn handle_side(
    world: &mut World,
    unit: Entity,
    other: Option<Entity>,
    mask: [u32; 2],
    event: &AuraEvent,
) {
    if mask == [0; 2] || world.get::<ActiveAuras>(unit).is_none() {
        return;
    }
    super::interrupt_auras(
        world,
        unit,
        interrupt_flags(mask, event.periodic),
        event.spell_id,
    );
    let event_spell = event.spell_id.and_then(|id| {
        world
            .get_resource::<SpellStore>()
            .and_then(|store| store.get(id))
            .cloned()
    });
    let event_not_a_proc = event_spell
        .as_ref()
        .is_some_and(|spell| attributes3(spell) & SPELL_ATTR3_NOT_A_PROC != 0);
    let standing = crate::stand_state::stand_state(world, unit).is_stand();
    let candidates: Vec<u32> = world
        .get::<ActiveAuras>(unit)
        .map(|auras| {
            auras
                .iter()
                .filter(|aura| standing || procs_while_sitting(world, aura))
                .filter(|aura| {
                    event.can_proc || triggered_can_proc(world, aura, event, event_not_a_proc)
                })
                .filter(|aura| proc_matches(world, aura, mask, event_spell.as_ref(), event))
                .map(|aura| aura.instance_id)
                .collect()
        })
        .unwrap_or_default();
    for id in candidates {
        try_proc(world, unit, other, id, event);
    }
}

/// `SPELL_ATTR4_ALLOW_PROC_WHILE_SITTING` (SharedDefines.h:603).
const SPELL_ATTR4_ALLOW_PROC_WHILE_SITTING: u32 = 0x0008_0000;

/// `Aura::GetProcEffectMask` (SpellAuras.cpp:1967-1969): an aura of a unit that sits,
/// sleeps or kneels procs only with `SPELL_ATTR4_ALLOW_PROC_WHILE_SITTING`.
fn procs_while_sitting(world: &World, aura: &AuraInstance) -> bool {
    world
        .get_resource::<SpellStore>()
        .and_then(|store| store.get(aura.spell_id))
        .and_then(|spell| spell.misc.as_ref())
        .is_some_and(|misc| misc.attributes[4] & SPELL_ATTR4_ALLOW_PROC_WHILE_SITTING != 0)
}

/// `SPELL_ATTR3_NOT_A_PROC`: a triggered spell with it procs auras like a cast one.
const SPELL_ATTR3_NOT_A_PROC: u32 = 0x200;
/// `SPELL_ATTR3_CAN_PROC_FROM_PROCS`: the aura procs from triggered spells too.
const SPELL_ATTR3_CAN_PROC_FROM_PROCS: u32 = 0x0400_0000;

fn attributes3(spell: &SpellInfo) -> u32 {
    spell.misc.as_ref().map_or(0, |misc| misc.attributes[3])
}

/// `Aura::GetProcEffectMask` for an event of a triggered spell: the aura procs when it
/// has `SPELL_ATTR3_CAN_PROC_FROM_PROCS` or the spell `SPELL_ATTR3_NOT_A_PROC`, but never
/// from its own trigger spell (`IsTriggeredByAura`). `PROC_ATTR_TRIGGERED_CAN_PROC`
/// (`spell_proc`) is not imported.
fn triggered_can_proc(
    world: &World,
    aura: &AuraInstance,
    event: &AuraEvent,
    event_not_a_proc: bool,
) -> bool {
    let own_trigger = aura
        .effects
        .iter()
        .any(|effect| effect.trigger_spell != 0 && Some(effect.trigger_spell) == event.spell_id);
    if own_trigger {
        return false;
    }
    event_not_a_proc
        || world
            .get_resource::<SpellStore>()
            .and_then(|store| store.get(aura.spell_id))
            .is_some_and(|spell| attributes3(spell) & SPELL_ATTR3_CAN_PROC_FROM_PROCS != 0)
}

/// `AuraEffect::CheckEffectProc` for `effect`: a breakable crowd-control effect
/// needs damage, and not its own spell's (TrinityCore exempts that while the aura is
/// at full duration, i.e. the applying hit; periodic ticks of a CC spell are not modelled).
fn effect_checks_proc(aura: &AuraInstance, effect: &AuraEffectState, event: &AuraEvent) -> bool {
    if !handlers::breaks_on_damage(effect.aura_type) {
        return true;
    }
    event.damage > 0.0 && event.spell_id != Some(aura.spell_id)
}

fn proc_mask(world: &World, aura: &AuraInstance) -> [u32; 2] {
    world
        .get_resource::<SpellStore>()
        .and_then(|store| store.get(aura.spell_id))
        .and_then(|spell| spell.aura_options.as_ref())
        .map_or([0; 2], |options| options.proc_type_mask)
}

fn proc_matches(
    world: &World,
    aura: &AuraInstance,
    mask: [u32; 2],
    event_spell: Option<&SpellInfo>,
    event: &AuraEvent,
) -> bool {
    //102351's tooltip requires damage taken, not a heal or fully absorbed hit.
    if aura.spell_id == crate::spell_cast::scripts::CENARION_WARD && event.damage <= 0.0 {
        return false;
    }
    if !scripts::check_proc(world, aura, event) {
        return false;
    }
    let proc_mask = proc_mask(world, aura);
    if proc_mask[0] & mask[0] == 0 && proc_mask[1] & mask[1] == 0 {
        return false;
    }
    let reflect_aura = aura
        .effects
        .iter()
        .any(|effect| handlers::reflects(effect.aura_type));
    if reflect_aura != event.reflected {
        return false;
    }
    // A scripted OnProc stands for its explicit TDB `spell_proc` row, which TC
    // honours whatever the effect types (e.g. 472885's aura468 death proc).
    if !aura.effects.iter().any(|effect| {
        handlers::can_proc(effect.aura_type) && effect_checks_proc(aura, effect, event)
    }) && !scripts::has_proc_script(world, aura.spell_id)
    {
        return false;
    }
    if mask[0] & SPELL_PROC_MASK == 0 {
        return true;
    }
    let family_mask = aura
        .effects
        .iter()
        .filter(|effect| handlers::can_proc(effect.aura_type))
        .fold([0u32; 4], |mut acc, effect| {
            (0..4).for_each(|word| acc[word] |= effect.class_mask[word]);
            acc
        });
    if family_mask == [0; 4] {
        return true;
    }
    event_spell
        .and_then(|spell| spell.class_options.as_ref())
        .is_some_and(|options| {
            options.spell_class_set == aura.class_set
                && (0..4).any(|word| options.spell_class_mask[word] & family_mask[word] != 0)
        })
}

/// Chance in percent, updating the RPPM attempt timer.
fn proc_chance(world: &mut World, unit: Entity, id: u32, now: f64) -> f32 {
    let Some(aura) = world
        .get::<ActiveAuras>(unit)
        .and_then(|auras| auras.get(id))
    else {
        return 0.0;
    };
    let timers = aura.proc;
    let Some(spell) = world
        .get_resource::<SpellStore>()
        .and_then(|store| store.get(aura.spell_id))
        .cloned()
    else {
        return 0.0;
    };
    let options = spell.aura_options.as_deref();
    let ppm = options
        .and_then(|options| options.procs_per_minute)
        .map_or(0.0, |ppm| ppm.base_proc_rate);
    let chance = if ppm > 0.0 {
        let average_interval = 60.0 / f64::from(ppm);
        let since_attempt = (now - timers.last_attempt_at).min(PPM_MAX_ATTEMPT_GAP);
        let since_success = (now - timers.last_success_at).min(1000.0);
        let bad_luck = (1.0 + (since_success / average_interval - 1.5) * 3.0).max(1.0);
        (bad_luck * f64::from(ppm) * since_attempt / 60.0).clamp(0.0, 1.0) as f32 * 100.0
    } else {
        options.map_or(0.0, |options| options.proc_chance as f32)
    };
    if let Some(aura) = world
        .get_mut::<ActiveAuras>(unit)
        .and_then(|auras| auras.into_inner().get_mut(id))
    {
        aura.proc.last_attempt_at = now;
    }
    spell_mods::modify(world, unit, &spell, SpellModOp::ProcChance, chance)
}

fn try_proc(world: &mut World, unit: Entity, other: Option<Entity>, id: u32, event: &AuraEvent) {
    let now = aura_now(world);
    let ready = world
        .get::<ActiveAuras>(unit)
        .and_then(|auras| auras.get(id))
        .is_some_and(|aura| now >= aura.proc.next_ready_at);
    if !ready {
        return;
    }
    let chance = proc_chance(world, unit, id, now);
    if chance <= 0.0 || rand::random::<f32>() * 100.0 >= chance {
        return;
    }
    let Some(aura) = start_proc_cooldown(world, unit, id, now) else {
        return;
    };
    for effect in aura.effects.iter().filter(|effect| {
        matches!(
            effect.aura_type,
            PROC_TRIGGER_SPELL | PROC_TRIGGER_SPELL_WITH_VALUE
        ) && effect.trigger_spell != 0
    }) {
        crate::spell_cast::cast_triggered(
            world,
            unit,
            effect.trigger_spell,
            Some(other.unwrap_or(unit)),
            PROC_TRIGGER_DEPTH,
        );
    }
    if break_crowd_control(world, unit, &aura, event) {
        return;
    }
    scripts::run_proc(world, unit, &aura, other, event);
    if aura.charges > 0 {
        super::spend_charge(world, unit, id);
    }
}

/// `HandleBreakableCCAuraProc`: the damage comes off each breakable effect's amount;
/// one at 0 or below removes the aura. True when the aura was removed.
fn break_crowd_control(
    world: &mut World,
    unit: Entity,
    aura: &AuraInstance,
    event: &AuraEvent,
) -> bool {
    let Some(mut auras) = world.get_mut::<ActiveAuras>(unit) else {
        return false;
    };
    let Some(stored) = auras.bypass_change_detection().get_mut(aura.instance_id) else {
        return false;
    };
    let mut broken = false;
    for effect in stored.effects.iter_mut().filter(|effect| {
        handlers::breaks_on_damage(effect.aura_type) && effect_checks_proc(aura, effect, event)
    }) {
        effect.amount -= event.damage;
        broken |= effect.amount <= 0.0;
    }
    if broken {
        super::remove_instance(
            world,
            unit,
            aura.instance_id,
            super::RemoveReason::Interrupted,
        );
    }
    broken
}

fn start_proc_cooldown(world: &mut World, unit: Entity, id: u32, now: f64) -> Option<AuraInstance> {
    let cooldown_ms = {
        let aura = world.get::<ActiveAuras>(unit)?.get(id)?;
        world
            .get_resource::<SpellStore>()
            .and_then(|store| store.get(aura.spell_id))
            .and_then(|spell| spell.aura_options.as_ref())
            .map_or(0, |options| options.proc_category_recovery_ms.max(0))
    };
    let mut auras = world.get_mut::<ActiveAuras>(unit)?;
    let aura = auras.bypass_change_detection().get_mut(id)?;
    aura.proc.last_success_at = now;
    aura.proc.next_ready_at = now + f64::from(cooldown_ms) / 1000.0;
    Some(aura.clone())
}
